// src/components/Filters.tsx
import React, { useState } from 'react';
import { useDispatch } from 'react-redux';
import { fetchArticles, setFilters } from '../store/newsReducer';
import { Form, Button, Row, Col } from 'react-bootstrap';

const Filters: React.FC = () => {
  const dispatch = useDispatch();
  const [source, setSource] = useState('newsapi');
  const [date, setDate] = useState('');
  const [category, setCategory] = useState('');
  const [author, setAuthor] = useState('');
  const [query, setQuery] = useState('');

  const handleFilterChange = () => {
    dispatch(setFilters({ date, category, author, source, query }) as any);
    dispatch(fetchArticles({ query, source, date, category, author }) as any);
  };

  return (
    <div className="filters mb-4 p-3 bg-light rounded">
      <Row>
        <Col>
          <Form.Label>Keyword</Form.Label>
          <Form.Control type="text" value={query} onChange={(e) => setQuery(e.target.value)} />
        </Col>
      </Row>
      <div className="text-center mt-3">
        <Button onClick={handleFilterChange}>Apply Filters</Button>
      </div>
    </div>
  );
};

export default Filters;
